'use client'

import { useState, useEffect } from 'react'
import { supabase } from '@/lib/supabase'
import dynamic from 'next/dynamic'
import MainMenu from '@/components/MainMenu'
import { Filter, X, Globe, Instagram, ExternalLink, LogIn, LogOut, Download, Upload, Plus, Lock } from 'lucide-react'
import { isNew } from '@/utils/helper'
import { useRouter } from 'next/navigation'
import BoutonFavori from '@/components/BoutonFavori'

const Map = dynamic(() => import('@/components/Map'), {
  ssr: false
})

export default function CartePage() {
  const router = useRouter()
  const [lieux, setLieux] = useState([])
  const [villes, setVilles] = useState([])
  const [categories, setCategories] = useState([])
  const [filtresActifs, setFiltresActifs] = useState({ types: [], villes: [] })
  const [showFilters, setShowFilters] = useState(false)
  const [selectedLieu, setSelectedLieu] = useState(null)
  const [isAdmin, setIsAdmin] = useState(false)
  const [showLogin, setShowLogin] = useState(false)
  const [loginData, setLoginData] = useState({ email: '', password: '' })
  
  // États pour l'édition
  const [showEditSidebar, setShowEditSidebar] = useState(false)
  const [editingId, setEditingId] = useState(null)
  const [formData, setFormData] = useState({ 
    nom: '', 
    types: [], 
    ville: '',
    description: '',
    website: '',
    instagram: ''
  })
  const [typeInput, setTypeInput] = useState('')
  const [villeInput, setVilleInput] = useState('')
  const [showTypeSuggestions, setShowTypeSuggestions] = useState(false)
  const [showVilleSuggestions, setShowVilleSuggestions] = useState(false)
  const [selectedSuggestionIndex, setSelectedSuggestionIndex] = useState(-1)
  const [selectedVilleSuggestionIndex, setSelectedVilleSuggestionIndex] = useState(-1)

  const TAG_COLORS = [
    "#9FFFCA", "#FFAEFF", "#FFAC88", "#C6BBFF", "#F9FFBD", "#A8FFD8",
    "#FC9F9F", "#FF8FD4", "#FFB7E3", "#FFB39A", "#FFD1B8", "#B8C7FF",
    "#D6D0FF", "#FFF3A0", "#EFFF9F", "#8FD6FF", "#AEE8FF", "#BFF2E8", "#FFDDEB",
  ]

  function getColorForType(type) {
    let hash = 0
    for (let i = 0; i < type.length; i++) {
      hash = type.charCodeAt(i) + ((hash << 5) - hash)
    }
    return TAG_COLORS[Math.abs(hash) % TAG_COLORS.length]
  }

  useEffect(() => {
    checkUser()
    loadData()
  }, [])

  const checkUser = async () => {
    const { data: { session } } = await supabase.auth.getSession()
    setIsAdmin(!!session)
  }

  const handleLogin = async () => {
    try {
      const { error } = await supabase.auth.signInWithPassword({
        email: loginData.email,
        password: loginData.password,
      })
      if (error) throw error
      setIsAdmin(true)
      setShowLogin(false)
      setLoginData({ email: '', password: '' })
      alert('Connexion réussie !')
    } catch (error) {
      alert('Erreur de connexion : ' + error.message)
    }
  }

  const handleLogout = async () => {
    await supabase.auth.signOut()
    setIsAdmin(false)
    alert('Déconnexion réussie')
  }

  const loadData = async () => {
    await Promise.all([loadLieux(), loadVilles(), loadCategories()])
  }

  const loadLieux = async () => {
    const { data, error } = await supabase
      .from('lieux')
      .select('*')
      .order('nom', { ascending: true })
    
    if (!error && data) setLieux(data)
  }

  const loadVilles = async () => {
    const { data, error } = await supabase
      .from('villes')
      .select('*')
      .order('nom', { ascending: true })
    
    if (!error && data) setVilles(data)
  }

  const loadCategories = async () => {
    const { data, error } = await supabase
      .from('categories')
      .select('nom')
      .order('nom', { ascending: true })
    
    if (!error && data) setCategories(data.map(c => c.nom))
  }

  const toggleFiltre = (type, value) => {
    setFiltresActifs(prev => {
      const arr = prev[type]
      const newArr = arr.includes(value)
        ? arr.filter(v => v !== value)
        : [...arr, value]
      return { ...prev, [type]: newArr }
    })
  }

  // Fonction de normalisation pour la comparaison
  const normalizeString = (str) => {
    if (!str || typeof str !== 'string') return ''
    return str
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .trim()
  }

  // Vérifier les doublons
  const checkDuplicate = (nom) => {
    const normalizedNom = normalizeString(nom)
    return lieux.some(lieu => 
      lieu.id !== editingId && normalizeString(lieu.nom) === normalizedNom
    )
  }

  // Fonction pour éditer un lieu
  const editerLieu = (lieu) => {
    if (!isAdmin) return
    
    setFormData({ 
      nom: lieu.nom, 
      types: lieu.types, 
      ville: lieu.ville,
      description: lieu.description || '',
      website: lieu.website || '',
      instagram: lieu.instagram || ''
    })
    setEditingId(lieu.id)
    setShowEditSidebar(true)
    setSelectedLieu(null) // Ferme la sidebar de détails
  }

  // Fonction pour supprimer un lieu
  const supprimerLieu = async (id, ville) => {
    if (!isAdmin) return

    if (confirm('Supprimer ce lieu ?')) {
      const { error } = await supabase.from('lieux').delete().eq('id', id)
      if (error) {
        alert('Erreur lors de la suppression : ' + error.message)
        return
      }

      const { count, error: countError } = await supabase
        .from('lieux')
        .select('*', { count: 'exact', head: true })
        .eq('ville', ville)

      if (countError) {
        console.error('Erreur vérification ville:', countError)
      } else if (count === 0) {
        const { error: delError } = await supabase
          .from('villes')
          .delete()
          .eq('nom', ville)

        if (delError) console.error('Erreur suppression ville:', delError)
      }

      loadLieux()
      loadVilles()
      setSelectedLieu(null)
    }
  }

  // Ajouter/Modifier un lieu
  const ajouterLieu = async () => {
    if (!isAdmin) {
      alert('Vous devez être connecté en tant qu\'admin')
      return
    }

    if (!formData.nom || formData.types.length === 0 || !formData.ville) {
      alert('Veuillez remplir tous les champs obligatoires')
      return
    }

    if (checkDuplicate(formData.nom)) {
      alert(`Un lieu nommé "${formData.nom}" existe déjà dans la base de données.`)
      return
    }

    try {
      const lieuData = {
        nom: formData.nom,
        types: formData.types,
        ville: formData.ville,
        description: formData.description || null,
        website: formData.website || null,
        instagram: formData.instagram || null
      }

      if (editingId) {
        const { error } = await supabase
          .from('lieux')
          .update(lieuData)
          .eq('id', editingId)
        
        if (error) throw error
      } else {
        const { error } = await supabase
          .from('lieux')
          .insert([lieuData])
        
        if (error) throw error
      }

      resetForm()
      loadLieux()
      alert(editingId ? 'Lieu modifié !' : 'Lieu ajouté !')
    } catch (error) {
      alert('Erreur : ' + error.message)
    }
  }

  const resetForm = () => {
    setFormData({ 
      nom: '', 
      types: [], 
      ville: '',
      description: '',
      website: '',
      instagram: ''
    })
    setEditingId(null)
    setShowEditSidebar(false)
    setTypeInput('')
    setVilleInput('')
    setSelectedSuggestionIndex(-1)
    setSelectedVilleSuggestionIndex(-1)
  }

  // Autocomplétion pour les types
  const getTypeSuggestions = () => {
    if (!typeInput) return []
    
    const normalized = normalizeString(typeInput)
    return categories
      .filter(c => !formData.types.includes(c))
      .filter(c => normalizeString(c).includes(normalized))
      .sort((a, b) => {
        const aNorm = normalizeString(a)
        const bNorm = normalizeString(b)
        const aStarts = aNorm.startsWith(normalized)
        const bStarts = bNorm.startsWith(normalized)
        if (aStarts && !bStarts) return -1
        if (!aStarts && bStarts) return 1
        return a.localeCompare(b)
      })
  }

  const handleTypeInputKeyDown = (e) => {
    const suggestions = getTypeSuggestions()
    
    if (e.key === 'Tab' && suggestions.length > 0) {
      e.preventDefault()
      const selectedType = selectedSuggestionIndex >= 0 
        ? suggestions[selectedSuggestionIndex] 
        : suggestions[0]
      ajouterType(selectedType)
    } else if (e.key === 'ArrowDown') {
      e.preventDefault()
      setSelectedSuggestionIndex(prev => 
        prev < suggestions.length - 1 ? prev + 1 : prev
      )
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      setSelectedSuggestionIndex(prev => prev > 0 ? prev - 1 : -1)
    } else if (e.key === 'Enter' && selectedSuggestionIndex >= 0) {
      e.preventDefault()
      ajouterType(suggestions[selectedSuggestionIndex])
    }
  }

  const ajouterType = async (type) => {
    if (!isAdmin) return
    
    if (type && !formData.types.includes(type)) {
      setFormData({ ...formData, types: [...formData.types, type] })
    }
    
    if (type && !categories.includes(type)) {
      await supabase.from('categories').insert([{ nom: type }])
      loadCategories()
    }
    
    setTypeInput('')
    setShowTypeSuggestions(false)
    setSelectedSuggestionIndex(-1)
  }

  const retirerType = (type) => {
    if (!isAdmin) return
    setFormData({ ...formData, types: formData.types.filter(t => t !== type) })
  }

  // Autocomplétion pour les villes
  const getVilleSuggestions = () => {
    if (!villeInput) return []

    const normalizedInput = normalizeString(villeInput)

    return villes
      .filter(v => normalizeString(v.nom).includes(normalizedInput))
      .sort((a, b) => {
        const aNorm = normalizeString(a.nom)
        const bNorm = normalizeString(b.nom)
        const aStarts = aNorm.startsWith(normalizedInput)
        const bStarts = bNorm.startsWith(normalizedInput)
        if (aStarts && !bStarts) return -1
        if (!aStarts && bStarts) return 1
        return a.nom.localeCompare(b.nom)
      })
  }

  const handleVilleInputKeyDown = (e) => {
    const suggestions = getVilleSuggestions()

    if (e.key === 'Tab' && suggestions.length > 0) {
      e.preventDefault()
      const selectedVille =
        selectedVilleSuggestionIndex >= 0
          ? suggestions[selectedVilleSuggestionIndex]
          : suggestions[0]

      selectionnerVille(selectedVille.nom)
    } 
    else if (e.key === 'ArrowDown') {
      e.preventDefault()
      setSelectedVilleSuggestionIndex(prev =>
        prev < suggestions.length - 1 ? prev + 1 : prev
      )
    } 
    else if (e.key === 'ArrowUp') {
      e.preventDefault()
      setSelectedVilleSuggestionIndex(prev =>
        prev > 0 ? prev - 1 : -1
      )
    } 
    else if (e.key === 'Enter' && selectedVilleSuggestionIndex >= 0) {
      e.preventDefault()
      selectionnerVille(suggestions[selectedVilleSuggestionIndex].nom)
    }
  }

  const selectionnerVille = async (villeNom) => {
    if (!isAdmin || !villeNom) return

    setFormData({ ...formData, ville: villeNom })

    if (!villes.some(v => normalizeString(v.nom) === normalizeString(villeNom))) {
      console.log(`Géocodage de "${villeNom}"...`)
      const coords = await geocodeVille(villeNom)

      const nouvelleVille = coords
        ? { nom: villeNom, latitude: coords.latitude, longitude: coords.longitude }
        : { nom: villeNom }

      await supabase.from('villes').insert([nouvelleVille])
      loadVilles()
    }

    setVilleInput('')
    setShowVilleSuggestions(false)
    setSelectedVilleSuggestionIndex(-1)
  }

  const geocodeVille = async (nomVille) => {
    if (!nomVille || typeof nomVille !== 'string') return null

    try {
      const response = await fetch(
        `https://nominatim.openstreetmap.org/search?` + 
        new URLSearchParams({
          q: `${nomVille}, France`,
          format: 'json',
          limit: 1,
          countrycodes: 'fr'
        }),
        {
          headers: {
            'User-Agent': 'HexaIndex/1.0'
          }
        }
      )

      const data = await response.json()
      if (data && data.length > 0) {
        return {
          latitude: parseFloat(data[0].lat),
          longitude: parseFloat(data[0].lon)
        }
      }

      return null
    } catch (error) {
      console.error('Erreur de géocodage:', error)
      return null
    }
  }

  const exporterDonnees = () => {
    const data = { lieux, categories, villes }
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `lieux-export-${new Date().toISOString().split('T')[0]}.json`
    a.click()
    URL.revokeObjectURL(url)
  }

  const importerDonnees = async (e) => {
    if (!isAdmin) {
      alert('Vous devez être connecté en tant qu\'admin')
      return
    }
    
    const file = e.target.files?.[0]
    if (!file) return
    
    const reader = new FileReader()
    reader.onload = async (event) => {
      try {
        const data = JSON.parse(event.target.result)
        if (data.lieux && confirm('Importer ces données ? Cela remplacera vos données actuelles.')) {
          await supabase.from('lieux').delete().neq('id', 0)
          await supabase.from('lieux').insert(data.lieux.map(l => ({
            nom: l.nom,
            types: l.types,
            ville: l.ville,
            description: l.description,
            website: l.website,
            instagram: l.instagram
          })))
          
          loadData()
          alert('Données importées avec succès !')
        }
      } catch (error) {
        alert('Erreur lors de l\'import : ' + error.message)
      }
    }
    reader.readAsText(file)
    e.target.value = ''
  }

  // Filtrer les lieux
  const lieuxFiltres = lieux.filter(lieu => {
    const matchTypes = filtresActifs.types.length === 0 || 
      filtresActifs.types.some(t => lieu.types.includes(t))
    const matchVilles = filtresActifs.villes.length === 0 || 
      filtresActifs.villes.includes(lieu.ville)
    return matchTypes && matchVilles
  })

  const typesSuggestions = getTypeSuggestions()
  const villesSuggestions = getVilleSuggestions()

  return (
    <div className="min-h-screen bg-gray-50 p-4">
      {/* Modal de connexion */}
      {showLogin && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-lg p-6 max-w-md w-full">
            <div className="flex items-center gap-3 mb-6">
              <Lock className="text-blue-600" size={24} />
              <h2 className="text-2xl font-bold">Connexion</h2>
            </div>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-2">Email</label>
                <input
                  type="email"
                  value={loginData.email}
                  onChange={(e) => setLoginData({ ...loginData, email: e.target.value })}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                  placeholder="admin@exemple.com"
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-2">Mot de passe</label>
                <input
                  type="password"
                  value={loginData.password}
                  onChange={(e) => setLoginData({ ...loginData, password: e.target.value })}
                  onKeyPress={(e) => e.key === 'Enter' && handleLogin()}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500"
                  placeholder="••••••••"
                />
              </div>
              <div className="flex gap-3">
                <button 
                  onClick={handleLogin} 
                  className="flex-1 bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700 font-medium"
                >
                  Se connecter
                </button>
                <button 
                  onClick={() => setShowLogin(false)} 
                  className="bg-gray-300 text-gray-700 px-6 py-2 rounded-lg hover:bg-gray-400"
                >
                  Annuler
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Sidebar lieu sélectionné */}
      {selectedLieu && (
        <div className="fixed right-0 top-0 h-full w-[90vw] max-w-[400px] bg-white shadow-2xl z-50 overflow-y-auto animate-slide-in">
          <div className="p-6">
            <div className="flex justify-between items-start mb-6">
              <div className="flex-1 pr-4">
                <div className="flex items-center gap-2 mb-2">
                  <h2 className="text-2xl font-bold text-gray-800">{selectedLieu.nom}
                  </h2>
          
  <BoutonFavori lieu={selectedLieu} />
                  {isNew(selectedLieu.created_at) && (
                    <span className="bg-green-500 text-white text-xs font-bold px-2 py-1 rounded">
                      NOUVEAU
                    </span>
                  )}
                </div>
                <div className="flex flex-wrap gap-2 mb-2">
                  {selectedLieu.types.map(type => (
                    <span 
                      key={type}
                      style={{ backgroundColor: getColorForType(type), color: '#202020ff' }}
                      className="px-3 py-1 rounded-full text-sm"
                    >
                      {type}
                    </span>
                  ))}
                </div>
                <p className="text-gray-600">📍 {selectedLieu.ville}</p>
              </div>
              <button
                onClick={() => setSelectedLieu(null)}
                className="text-gray-400 hover:text-gray-600 p-2 transition-colors flex-shrink-0"
              >
                <X size={24} />
              </button>
            </div>

            {selectedLieu.description && (
              <div className="mb-6">
                <h3 className="font-semibold text-gray-700 mb-2">Description</h3>
                <p className="text-gray-600 leading-relaxed">{selectedLieu.description}</p>
              </div>
            )}

            {(selectedLieu.website || selectedLieu.instagram) && (
              <div className="space-y-3 mb-6">
                {selectedLieu.website && (
                  <a href={selectedLieu.website} target="_blank" rel="noopener noreferrer" className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors">
                    <Globe size={20} className="text-blue-600 flex-shrink-0" />
                    <span className="text-gray-700 font-medium">Voir le site web</span>
                    <ExternalLink size={16} className="text-gray-400 ml-auto flex-shrink-0" />
                  </a>
                )}
                
                {selectedLieu.instagram && (
                  <a href={selectedLieu.instagram.startsWith('http') ? selectedLieu.instagram : `https://instagram.com/${selectedLieu.instagram.replace('@', '')}`} target="_blank" rel="noopener noreferrer" className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors">
                    <Instagram size={20} className="text-pink-600 flex-shrink-0" />
                    <span className="text-gray-700 font-medium">Voir sur Instagram</span>
                    <ExternalLink size={16} className="text-gray-400 ml-auto flex-shrink-0" />
                  </a>
                )}
              </div>
            )}

            {/* Boutons Modifier et Supprimer */}
            {isAdmin && (
              <div className="pt-6 border-t flex gap-2">
                <button
                  onClick={() => {
                    editerLieu(selectedLieu)
                    setSelectedLieu(null)
                  }}
                  className="flex-1 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors"
                >
                  Modifier
                </button>
                <button
                  onClick={() => {
                    supprimerLieu(selectedLieu.id, selectedLieu.ville)
                    setSelectedLieu(null)
                  }}
                  className="flex-1 bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700 transition-colors"
                >
                  Supprimer
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Sidebar d'édition */}
      {showEditSidebar && isAdmin && (
        <div className="fixed right-0 top-0 h-full w-[90vw] max-w-[500px] bg-white shadow-2xl z-50 overflow-y-auto animate-slide-in">
          <div className="p-6">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-gray-800">
                {editingId ? 'Modifier le lieu' : 'Nouveau lieu'}
              </h2>
              <button
                onClick={resetForm}
                className="text-gray-400 hover:text-gray-600 p-2 transition-colors"
              >
                <X size={24} />
              </button>
            </div>
            
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-2">Nom</label>
                <input
                  type="text"
                  value={formData.nom}
                  onChange={(e) => setFormData({ ...formData, nom: e.target.value })}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="Nom du lieu"
                />
                {formData.nom && checkDuplicate(formData.nom) && (
                  <p className="text-red-600 text-sm mt-1">⚠️ Un lieu avec ce nom existe déjà</p>
                )}
              </div>

              <div className="relative">
                <label className="block text-sm font-medium mb-2">
                  Type de lieux
                  {typesSuggestions.length > 0 && (
                    <span className="text-xs text-gray-500 ml-2">(Tab ou ↓↑)</span>
                  )}
                </label>
                <input
                  type="text"
                  value={typeInput}
                  onChange={(e) => {
                    setTypeInput(e.target.value)
                    setShowTypeSuggestions(true)
                    setSelectedSuggestionIndex(-1)
                  }}
                  onKeyDown={handleTypeInputKeyDown}
                  onFocus={() => setShowTypeSuggestions(true)}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="Rechercher un type..."
                />
                {showTypeSuggestions && typeInput && (
                  <div className="absolute z-10 w-full mt-1 bg-white border rounded-lg shadow-lg max-h-60 overflow-y-auto">
                    {typesSuggestions.map((cat, index) => (
                      <div
                        key={cat}
                        onClick={() => ajouterType(cat)}
                        className={`px-4 py-2 cursor-pointer ${
                          index === selectedSuggestionIndex ? 'bg-blue-100' : 'hover:bg-blue-50'
                        }`}
                      >
                        {cat}
                        {index === 0 && <span className="text-xs text-gray-500 ml-2">(Tab)</span>}
                      </div>
                    ))}
                    {typeInput && !categories.some(c => normalizeString(c) === normalizeString(typeInput)) && (
                      <div
                        onClick={() => ajouterType(typeInput)}
                        className="px-4 py-2 hover:bg-green-50 cursor-pointer text-green-700 font-medium border-t"
                      >
                        + Créer "{typeInput}"
                      </div>
                    )}
                  </div>
                )}
                <div className="flex flex-wrap gap-2 mt-2">
                  {formData.types.map(type => (
                    <span 
                      key={type} 
                      style={{ backgroundColor: getColorForType(type), color: '#202020ff' }}
                      className="px-3 py-1 rounded-full text-sm flex items-center gap-2"
                    >
                      {type}
                      <X size={14} className="cursor-pointer" onClick={() => retirerType(type)} />
                    </span>
                  ))}
                </div>
              </div>

              <div className="relative">
                <label className="block text-sm font-medium mb-2">
                  Ville
                  {villesSuggestions.length > 0 && (
                    <span className="text-xs text-gray-500 ml-2">(Tab ou ↓↑)</span>
                  )}
                </label>
                <input
                  type="text"
                  value={villeInput || formData.ville}
                  onChange={(e) => {
                    setVilleInput(e.target.value)
                    setShowVilleSuggestions(true)
                    setSelectedVilleSuggestionIndex(-1)
                  }}
                  onKeyDown={handleVilleInputKeyDown}
                  onFocus={() => setShowVilleSuggestions(true)}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="Rechercher une ville..."
                />
                {showVilleSuggestions && villeInput && (
                  <div className="absolute z-10 w-full mt-1 bg-white border rounded-lg shadow-lg max-h-60 overflow-y-auto">
                    {villesSuggestions.map((ville, index) => (
                      <div
                        key={ville.id || ville.nom + index}
                        onClick={() => selectionnerVille(ville.nom)}
                        className={`px-4 py-2 cursor-pointer ${
                          index === selectedVilleSuggestionIndex ? 'bg-blue-100' : 'hover:bg-blue-50'
                        }`}
                      >
                        {ville.nom}
                        {index === 0 && <span className="text-xs text-gray-500 ml-2">(Tab)</span>}
                      </div>
                    ))}
                    {villeInput && !villes.some(v => normalizeString(v.nom) === normalizeString(villeInput)) && (
                      <div
                        onClick={() => selectionnerVille(villeInput)}
                        className="px-4 py-2 hover:bg-green-50 cursor-pointer text-green-700 font-medium border-t"
                      >
                        + Créer "{villeInput}"
                      </div>
                    )}
                  </div>
                )}
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">Description</label>
                <textarea
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent min-h-[100px]"
                  placeholder="Décrivez le lieu..."
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">Site web</label>
                <input
                  type="url"
                  value={formData.website}
                  onChange={(e) => setFormData({ ...formData, website: e.target.value })}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="https://exemple.com"
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">Instagram</label>
                <input
                  type="text"
                  value={formData.instagram}
                  onChange={(e) => setFormData({ ...formData, instagram: e.target.value })}
                  className="w-full px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="@nomducompte"
                />
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  onClick={ajouterLieu}
                  disabled={formData.nom && checkDuplicate(formData.nom)}
                  className="flex-1 bg-green-600 text-white px-6 py-3 rounded-lg hover:bg-green-700 disabled:bg-gray-400 disabled:cursor-not-allowed font-medium"
                >
                  {editingId ? '✓ Modifier' : '+ Ajouter'}
                </button>
                <button
                  onClick={resetForm}
                  className="bg-gray-300 text-gray-700 px-6 py-3 rounded-lg hover:bg-gray-400 font-medium"
                >
                  Annuler
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <div className="w-[95%] max-w-[95rem] mx-auto">
        
        {/* Header */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
          <div className="flex justify-between items-start mb-4">
            <div>
              <h1 className="text-3xl font-bold text-gray-800">Carte des lieux</h1>
              <h3 className="text-1xl font-bold text-gray-800">Index de ressources pour design·euse·r·s graphique</h3>
              {isAdmin && <p className="text-sm text-green-600 mt-1">Mode administrateur</p>}
            </div>
            
            {/* Boutons admin */}
            <div className="flex gap-3">
              {!isAdmin ? (
                <button
                  onClick={() => setShowLogin(true)}
                  className="bg-gray-100 text-white px-4 py-2 rounded-lg hover:bg-gray-200 flex items-center gap-2"
                >
                  <LogIn size={20} />
                  Connexion
                </button>
              ) : (
                <>
                  <button
                    onClick={exporterDonnees}
                    className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 flex items-center gap-2"
                  >
                    <Download size={20} />
                    Exporter
                  </button>
                  <label className="bg-purple-600 text-white px-4 py-2 rounded-lg hover:bg-purple-700 flex items-center gap-2 cursor-pointer">
                    <Upload size={20} />
                    Importer
                    <input
                      type="file"
                      accept=".json"
                      onChange={importerDonnees}
                      className="hidden"
                    />
                  </label>
                  <button
                    onClick={() => {
                      resetForm()
                      setShowEditSidebar(true)
                    }}
                    className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 flex items-center gap-2"
                  >
                    <Plus size={20} />
                    Ajouter
                  </button>
                  <button
                    onClick={handleLogout}
                    className="bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700 flex items-center gap-2"
                  >
                    <LogOut size={20} />
                    Déconnexion
                  </button>
                </>
              )}
            </div>
          </div>

          <div className="mt-4">
            <MainMenu />
          </div>

          {/* Bouton filtres */}
          <div className="mt-4 flex justify-between items-center">
            <div className="text-sm text-gray-500">
              {lieuxFiltres.length} lieu{lieuxFiltres.length > 1 ? 'x' : ''} affiché{lieuxFiltres.length > 1 ? 's' : ''}
            </div>
            <button
              onClick={() => setShowFilters(!showFilters)}
              className={`px-4 py-2 rounded-lg flex items-center gap-2 ${
                showFilters ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-700'
              }`}
            >
              <Filter size={20} />
              Filtres
              {(filtresActifs.types.length + filtresActifs.villes.length > 0) && (
                <span className="bg-white text-blue-600 rounded-full w-6 h-6 flex items-center justify-center text-sm font-bold">
                  {filtresActifs.types.length + filtresActifs.villes.length}
                </span>
              )}
            </button>
          </div>

          {/* Panneau de filtres */}
          {showFilters && (
            <div className="bg-gray-50 p-4 rounded-lg mt-4 border">
              <div className="grid md:grid-cols-2 gap-6">
                <div>
                  <h3 className="font-medium mb-2">Types</h3>
                  <div className="flex flex-wrap gap-2">
                    {categories.map(cat => (
                      <button
                        key={cat}
                        onClick={() => toggleFiltre('types', cat)}
                        className={`px-3 py-1 rounded-full text-sm transition-colors ${
                          filtresActifs.types.includes(cat)
                            ? 'bg-blue-600 text-white'
                            : 'bg-white border'
                        }`}
                        onMouseEnter={(e) => {
                          if (!filtresActifs.types.includes(cat)) {
                            e.currentTarget.style.backgroundColor = getColorForType(cat);
                            e.currentTarget.style.color = '#202020ff';
                          }
                        }}
                        onMouseLeave={(e) => {
                          if (!filtresActifs.types.includes(cat)) {
                            e.currentTarget.style.backgroundColor = 'white';
                            e.currentTarget.style.color = '';
                          }
                        }}
                      >
                        {cat}
                      </button>
                    ))}
                  </div>
                </div>
                <div>
                  <h3 className="font-medium mb-2">Villes</h3>
                  <div className="flex flex-wrap gap-2">
                    {villes.map(ville => (
                      <button
                        key={ville.nom}
                        onClick={() => toggleFiltre('villes', ville.nom)}
                        className={`px-3 py-1 rounded-full text-sm ${
                          filtresActifs.villes.includes(ville.nom)
                            ? 'bg-blue-600 text-white'
                            : 'bg-white border hover:bg-gray-100'
                        }`}
                      >
                        {ville.nom}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Carte en plein écran */}
        <div className="bg-white rounded-lg shadow-sm p-6">
          <div style={{ height: 'calc(100vh - 300px)', minHeight: '600px' }}>
            <Map 
              lieux={lieuxFiltres} 
              villes={villes} 
              filtresActifs={filtresActifs}
              onLieuClick={setSelectedLieu}
            />
          </div>
        </div>

      </div>
    </div>
  )
}